#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

TENANT_ID="cdf89f94-8c88-48fc-b11c-dd24af4380b4"
API_APP_ID="e8d3bb42-823a-43c6-902d-8920aafdbca7"
ANDROID_APP_ID="e0505a28-fb17-42d3-8bbd-e98bf44f089e"
WEB_APP_NAME="TwoPoint Admin Web"
REDIRECT_URIS=("https://admin.twopoint.dev/redirect/" "http://localhost:4322/redirect/")
FUNCTION_APP="func-twopoint-website-api"
ADMIN_ORIGIN="https://admin.twopoint.dev"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ACCESS_FILE="$REPO_ROOT/backend/Core/Shared/Access.fs"
ADMIN_CONFIG="$REPO_ROOT/frontend/Admin/config.json"

banner "Admin sign-in: Entra and CORS setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure"
say "The wizard uses the Azure CLI for each change. It asks before each change."
if az account show >/dev/null 2>&1 && az ad app show --id "$API_APP_ID" --query appId -o tsv >/dev/null 2>&1; then
  note "You are already signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login --tenant "$TENANT_ID" >/dev/null
fi
API_NAME=$(az ad app show --id "$API_APP_ID" --query displayName -o tsv)
SCOPE_ID=$(az ad app show --id "$API_APP_ID" --query "api.oauth2PermissionScopes[?value=='access_as_user'].id | [0]" -o tsv)
[[ -n "$SCOPE_ID" ]] || { warn "The API '$API_NAME' has no scope 'access_as_user'."; exit 1; }
note "API: $API_NAME ($API_APP_ID), scope access_as_user ($SCOPE_ID)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the \"$WEB_APP_NAME\" registration"
say "The admin signs in with this single-tenant registration."
step "Only spa redirect URIs: ${REDIRECT_URIS[*]}"
step "The delegated permission access_as_user on $API_NAME"
WEB_APP_ID=$(az ad app list --display-name "$WEB_APP_NAME" --query "[0].appId" -o tsv)
if [[ -n "$WEB_APP_ID" ]]; then
  note "The registration already exists ($WEB_APP_ID). The wizard sets its redirect URIs and permission again."
elif confirm "Create the registration '$WEB_APP_NAME'?"; then
  WEB_APP_ID=$(az ad app create --display-name "$WEB_APP_NAME" --sign-in-audience AzureADMyOrg --query appId -o tsv)
  printf '  %s✓ created%s %s (%s)\n' "$GREEN" "$RESET" "$WEB_APP_NAME" "$WEB_APP_ID"
else
  SKIPPED+=("Create the single-tenant registration '$WEB_APP_NAME', then run this wizard again")
  finish
  exit 0
fi
WEB_OBJECT_ID=$(az ad app show --id "$WEB_APP_ID" --query id -o tsv)
WEB_BODY=$(python3 -c '
import json, sys
print(json.dumps({
  "spa": {"redirectUris": sys.argv[3:]},
  "web": {"redirectUris": [], "implicitGrantSettings": {"enableAccessTokenIssuance": False, "enableIdTokenIssuance": False}},
  "publicClient": {"redirectUris": []},
  "requiredResourceAccess": [{"resourceAppId": sys.argv[1], "resourceAccess": [{"id": sys.argv[2], "type": "Scope"}]}],
}))' "$API_APP_ID" "$SCOPE_ID" "${REDIRECT_URIS[@]}")
az rest --method PATCH --uri "https://graph.microsoft.com/v1.0/applications/$WEB_OBJECT_ID" \
  --headers "Content-Type=application/json" --body "$WEB_BODY" >/dev/null
printf '  %s✓ set%s the redirect URIs and the permission\n' "$GREEN" "$RESET"
if ! az ad sp show --id "$WEB_APP_ID" >/dev/null 2>&1; then
  az ad sp create --id "$WEB_APP_ID" >/dev/null
  printf '  %s✓ created%s the enterprise application in the tenant\n' "$GREEN" "$RESET"
fi
python3 - "$ACCESS_FILE" "$ADMIN_CONFIG" "$WEB_APP_ID" <<'PY'
import json, re, sys
access, config, app_id = sys.argv[1:]
text = open(access).read()
text = re.sub(r'let clients = Map \[ "[0-9a-f-]+", "web" \]', f'let clients = Map [ "{app_id}", "web" ]', text)
open(access, "w").write(text)
settings = json.load(open(config))
for mode in settings.values():
    mode["clientId"] = app_id
open(config, "w").write(json.dumps(settings, indent=2) + "\n")
PY
printf '  %s✓ wrote%s the client ID to backend/Core/Shared/Access.fs and frontend/Admin/config.json\n' "$GREEN" "$RESET"
note "Commit the two files. The backend accepts the web client after the next backend deploy."
pause

# Each change to the API sends its full `api` object, so that no other API setting changes.
patch_api() {
  local body
  body=$(az ad app show --id "$API_APP_ID" --query api -o json | python3 -c "$1" "$WEB_APP_ID" "$SCOPE_ID")
  az rest --method PATCH --uri "https://graph.microsoft.com/v1.0/applications/$(az ad app show --id "$API_APP_ID" --query id -o tsv)" \
    --headers "Content-Type=application/json" --body "$body" >/dev/null
}

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Pre-authorize the web client on the API"
say "With the pre-authorization, the author gets no consent prompt at sign-in."
PREAUTHORIZED=$(az ad app show --id "$API_APP_ID" \
  --query "length(api.preAuthorizedApplications[?appId=='$WEB_APP_ID' && contains(delegatedPermissionIds, '$SCOPE_ID')])" -o tsv)
if [[ "${PREAUTHORIZED:-0}" -gt 0 ]]; then
  note "$API_NAME already pre-authorizes $WEB_APP_NAME. Nothing to do."
elif confirm "Pre-authorize '$WEB_APP_NAME' for access_as_user on '$API_NAME'?"; then
  patch_api '
import json, sys
api = json.load(sys.stdin)
web, scope = sys.argv[1], sys.argv[2]
others = [item for item in api.get("preAuthorizedApplications") or [] if item["appId"] != web]
api["preAuthorizedApplications"] = others + [{"appId": web, "delegatedPermissionIds": [scope]}]
print(json.dumps({"api": api}))'
  printf '  %s✓ pre-authorized%s %s\n' "$GREEN" "$RESET" "$WEB_APP_NAME"
else
  SKIPPED+=("Pre-authorize $WEB_APP_ID for access_as_user on $API_NAME (Expose an API > Add a client application)")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Move the API to v2.0 tokens"
say "The backend reads the client ID from the azp claim, and only a v2.0 token has azp."
TOKEN_VERSION=$(az ad app show --id "$API_APP_ID" --query "api.requestedAccessTokenVersion" -o tsv)
if [[ "$TOKEN_VERSION" == "2" ]]; then
  note "$API_NAME already gets v2.0 tokens. Nothing to do."
elif confirm "Set requestedAccessTokenVersion to 2 on '$API_NAME'?"; then
  patch_api '
import json, sys
api = json.load(sys.stdin)
api["requestedAccessTokenVersion"] = 2
print(json.dumps({"api": api}))'
  printf '  %s✓ set%s v2.0 tokens on %s\n' "$GREEN" "$RESET" "$API_NAME"
else
  SKIPPED+=("Set requestedAccessTokenVersion to 2 in the manifest of $API_NAME")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Let the admin origin call the Function App"
APP_RG=$(az functionapp list --query "[?name=='$FUNCTION_APP'].resourceGroup | [0]" -o tsv)
[[ -n "$APP_RG" ]] || { warn "Cannot find $FUNCTION_APP in this subscription."; exit 1; }
say "The admin sends the token in the Authorization header and sends no cookie."
note "Allowed origins now: $(az functionapp cors show -n "$FUNCTION_APP" -g "$APP_RG" --query "allowedOrigins" -o tsv | tr '\n' ' ')"
if az functionapp cors show -n "$FUNCTION_APP" -g "$APP_RG" --query "allowedOrigins" -o tsv | grep -qx "$ADMIN_ORIGIN"; then
  note "$FUNCTION_APP already allows $ADMIN_ORIGIN. Nothing to do."
elif confirm "Add $ADMIN_ORIGIN to the CORS origins of $FUNCTION_APP?"; then
  az functionapp cors add -n "$FUNCTION_APP" -g "$APP_RG" --allowed-origins "$ADMIN_ORIGIN" >/dev/null
  printf '  %s✓ added%s %s\n' "$GREEN" "$RESET" "$ADMIN_ORIGIN"
else
  SKIPPED+=("az functionapp cors add -n $FUNCTION_APP -g $APP_RG --allowed-origins $ADMIN_ORIGIN")
fi
SUPPORT_CREDENTIALS=$(az functionapp cors show -n "$FUNCTION_APP" -g "$APP_RG" --query "supportCredentials" -o tsv)
[[ "$SUPPORT_CREDENTIALS" == "false" ]] || warn "supportCredentials is '$SUPPORT_CREDENTIALS'. The admin needs no credentials, so set it to false."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Delete \"TwoPoint Admin Android\""
say "The Android app is retired, and the backend accepts only the web client."
note "Entra keeps a deleted registration for 30 days, and you can restore it in that time."
if ! az ad app show --id "$ANDROID_APP_ID" >/dev/null 2>&1; then
  note "The Android registration is already deleted. Nothing to do."
elif confirm "Delete the registration '$(az ad app show --id "$ANDROID_APP_ID" --query displayName -o tsv)' ($ANDROID_APP_ID)?"; then
  az ad app delete --id "$ANDROID_APP_ID"
  printf '  %s✓ deleted%s the Android registration\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Delete the registration $ANDROID_APP_ID (TwoPoint Admin Android)")
fi
pause

finish
}

run_wizard "$@"; exit
